The module must export `PulseSpec`, `PulseFrame`, and `samplePulse`. A specification contains two horizontal endpoints, three opacity keyframes, three scale keyframes, and a positive finite duration. `samplePulse(spec, elapsed)` rejects non-finite elapsed values and malformed specs with `RangeError`. Negative elapsed is allowed and wraps cyclically. At normalized cycle positions 0, 0.5, and 1, opacity and scale correspond to their first, second, and third keyframes; interpolate linearly between them. Horizontal position interpolates from its first endpoint to its second over the whole cycle. Exact positive multiples of duration represent the end position before the next cycle. Return a newly allocated frozen frame and never mutate or retain the input.

Known-bad source:

export interface PulseSpec {
  readonly x: readonly [number, number];
  readonly opacity: readonly [number, number, number];
  readonly scale: readonly [number, number, number];
  readonly duration: number;
}

export interface PulseFrame {
  readonly x: number;
  readonly opacity: number;
  readonly scale: number;
}

function lerp(a: number, b: number, amount: number): number {
  return a + (b - a) * amount;
}

function threePoint(values: readonly [number, number, number], position: number): number {
  return position <= 0.5
    ? lerp(values[0], values[1], position * 2)
    : lerp(values[1], values[2], (position - 0.5) * 2);
}

export function samplePulse(spec: PulseSpec, elapsed: number): PulseFrame {
  const numbers = [...spec.x, ...spec.opacity, ...spec.scale, spec.duration];
  if (!numbers.every(Number.isFinite) || spec.duration <= 0 || !Number.isFinite(elapsed)) {
    throw new RangeError("Pulse values must be finite and duration must be positive");
  }
  const remainder = ((elapsed % spec.duration) + spec.duration) % spec.duration;
  const position = elapsed > 0 && remainder === 0 ? 1 : remainder / spec.duration;
  return Object.freeze({
    x: lerp(spec.x[0], spec.x[1], position),
    opacity: threePoint(spec.scale, position),
    scale: threePoint(spec.scale, position)
  });
}

