import { PulseFrame, PulseSpec, samplePulse } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function close(actual: number, expected: number, message: string): void {
  if (Math.abs(actual - expected) > 1e-12) throw new Error(`${message}: expected ${expected}, got ${actual}`);
}
function frame(actual: PulseFrame, x: number, opacity: number, scale: number, message: string): void {
  close(actual.x, x, `${message} x`);
  close(actual.opacity, opacity, `${message} opacity`);
  close(actual.scale, scale, `${message} scale`);
}
function expectRangeError(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof RangeError, message);
}

const spec: PulseSpec = {
  x: [10, 30],
  opacity: [0.2, 1, 0.4],
  scale: [1, 2, 1.5],
  duration: 10
};
frame(samplePulse(spec, 0), 10, 0.2, 1, "cycle start");
frame(samplePulse(spec, 2.5), 15, 0.6, 1.5, "first-half interpolation");
frame(samplePulse(spec, 5), 20, 1, 2, "midpoint");
frame(samplePulse(spec, 7.5), 25, 0.7, 1.75, "second-half interpolation");
frame(samplePulse(spec, 10), 30, 0.4, 1.5, "exact duration is cycle end");
frame(samplePulse(spec, 20), 30, 0.4, 1.5, "later positive multiple is cycle end");
frame(samplePulse(spec, 12.5), 15, 0.6, 1.5, "positive elapsed wraps");
frame(samplePulse(spec, -2.5), 25, 0.7, 1.75, "negative elapsed wraps");
frame(samplePulse(spec, -10), 10, 0.2, 1, "negative exact multiple wraps to start");

const first = samplePulse(spec, 5);
const second = samplePulse(spec, 5);
assert(first !== second, "each sample is newly allocated");
assert(Object.isFrozen(first), "returned frame is frozen");

const mutable = {
  x: [0, 10] as [number, number],
  opacity: [0, 1, 0] as [number, number, number],
  scale: [1, 3, 1] as [number, number, number],
  duration: 4
};
const sampled = samplePulse(mutable, 2);
mutable.x[0] = 999;
mutable.opacity[1] = 999;
frame(sampled, 5, 1, 3, "input is not retained by returned frame");

expectRangeError(() => { samplePulse(spec, Number.NaN); }, "NaN elapsed is rejected");
expectRangeError(() => { samplePulse(spec, Number.POSITIVE_INFINITY); }, "infinite elapsed is rejected");
expectRangeError(() => { samplePulse({ ...spec, duration: 0 }, 0); }, "zero duration is rejected");
expectRangeError(() => { samplePulse({ ...spec, duration: -1 }, 0); }, "negative duration is rejected");
expectRangeError(() => { samplePulse({ ...spec, duration: Number.POSITIVE_INFINITY }, 0); }, "infinite duration is rejected");
expectRangeError(() => { samplePulse({ ...spec, opacity: [0, Number.NaN, 1] }, 0); }, "non-finite keyframe is rejected");
expectRangeError(() => {
  samplePulse({ x: [0] as unknown as readonly [number, number], opacity: [0, 1, 0], scale: [1, 2, 1], duration: 1 }, 0);
}, "malformed endpoint tuple is rejected");

